    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        sb.append('\n');
                        i++; // Skip the next character
                        break;
                    case 't':
                        sb.append('\t');
                        i++; // Skip the next character
                        break;
